import pandas as pd
import json

# Define the file paths
file_paths = [
    "/workspace/Shipment_Data_Q1_2017.csv",
    "/workspace/COO_Procurement-Logistics-Quality-Capacity_Catalog.csv",
    "/workspace/COO_Procurement-Logistics-Quality-Capacity_Catalog.xlsx"
]

# Initialize a list to hold valid dataframes
valid_dataframes = []

# Loop through each file path
for file_path in file_paths:
    try:
        # Attempt to read the file based on its extension
        if file_path.endswith('.csv'):
            df = pd.read_csv(file_path)
        elif file_path.endswith('.xlsx'):
            df = pd.read_excel(file_path)
        else:
            continue  # Skip files with unsupported extensions

        # Check if the file contains the required columns
        if 'Shipment_Cost_INR' in df.columns:
            valid_dataframes.append(df)
    except FileNotFoundError:
        print(f"File not found: {file_path}")
    except Exception as e:
        print(f"Error reading file {file_path}: {e}")

# Concatenate all valid dataframes
if valid_dataframes:
    combined_df = pd.concat(valid_dataframes, ignore_index=True)
else:
    print("No valid dataframes found.")
    exit()

# Filter the data for Q1 2017
filtered_df = combined_df[(combined_df['Year'] == 2017) & (combined_df['Month'] == 1)]

# Calculate the total shipment cost in INR
total_shipment_cost = filtered_df['Shipment_Cost_INR'].sum()

# Prepare the result
result = {
    "answer": total_shipment_cost,
    "details": {
        "total_shipment_cost": total_shipment_cost,
        "filtered_data": filtered_df.to_dict(orient='records')
    }
}

# Print the result
print("___RESULT___" + json.dumps(result, default=str))
